WITH valid_departments AS (SELECT * FROM departments WHERE dept_name = 'Finance'), DepartmentsStats AS (SELECT location, CASE WHEN budget >= 3222000 THEN 'high' WHEN budget >= 778000 THEN 'mid' ELSE 'low' END AS budget_bucket, ROUND(STDDEV(budget), 2) AS stddev_budget, SUM(CASE WHEN location = 'London' THEN 1 ELSE 0 END) AS london_count FROM valid_departments GROUP BY location, CASE WHEN budget >= 3222000 THEN 'high' WHEN budget >= 778000 THEN 'mid' ELSE 'low' END) SELECT * FROM DepartmentsStats WHERE stddev_budget < 80 ORDER BY location
